/*
Angelo De Florio
remote_power.js

Funzione che serve per accendere/spegnere
la Smart Socket da remoto, tramite interfaccia
seriale
*/
// Costanti
const motion  = Number(JSON.parse(msg.payload.motion));
const light   = Number(JSON.parse(msg.payload.light));
/*
Cooldown in millisecondi:
L'implementazione del cooldown è fondamentale per
assicurarsi che la Smart Socket non riceva
comandi di accensione/spegnimento ripetutamente
*/
const COOLDOWN = 5000; // 5 secondi

// Stato precedente del sensore
const previousMotion = context.get("previousMotion") || 0;

// Istante dell'ultimo comando
const lastAction = context.get("lastAction") || 0;
const now = Date.now();

/*
Funzione createDownlink(hex):
Funzionamento:
    Permette di creare un payload Downlink
    in JSON per inviare determinati
    comandi come l'accensione e lo spegnimento

Parametri:
    - hex:   valore esadecimale del payload
    - topic: specifica l'argomento MQTT su cui pubblicare il messaggio
*/
function createDownlink(hex, topic) {
    let out = {};
    out.topic = topic;
    out.payload = {
        "confirmed": false,
        "fPort": 85,
        "data": Buffer.from(hex, "hex").toString("base64")
    };
    return out;
}

// Rilevamento automatico ambiente in base ai lumens
if (light < 150 && light > 100) {
    node.status(
        {
            fill:"brown",
            shape:"ring",
            text:"Stanza: soggiorno " + light + " lumens"
        }
    );
} else if (light < 300 && light > 200) {
    node.status(
        {
            fill:"blue",
            shape:"ring",
            text: "Stanza: bagno " + light + " lumens"
        }
    );
} else {
    node.status(
        {
            fill:"red",
            shape:"ring",
            text: "Stanza: non definita " + light + " lumens"
        }
    )
}

// Memorizza lo stato attuale del sensore
context.set("previousMotion", motion);

// Esegui il comando solo sul passaggio 0 -> 1
const newMotionEvent = (motion === 1 && previousMotion === 0);

if (!newMotionEvent) {
    return null;
}

// Controllo cooldown
if (now - lastAction < COOLDOWN) {
    node.warn("Comando ignorato: cooldown attivo");
    return null;
}

// Memorizza il momento dell'azione
context.set("lastAction", now);

// Variabile che riceve lo stato globale della presa
let socketState = global.get("socketState") || 0;
let downlinkHex;

if (socketState !== 1) {
    downlinkHex = "080100ff";
    node.warn("Accensione remota della presa...");
    global.set("socketState", 1);
} else {
    downlinkHex = "080000ff";
    node.warn("Spegnimento remoto della presa...");
    global.set("socketState", 0);
}

// Creazione del payload downlink
return createDownlink(
    downlinkHex,
    "energysaver/downlink/24e124148c400670"
);

let out;
if (msg.payload) {
    out = {};
    out.topic = "energysaver/downlink/24e124148c400670";
    out.payload = {
        "confirmed" : false,
        "fPort"     : 85,
        "data"      : Buffer.from("080100ff", "hex").toString("base64")
    };
    return out;
}

out = {};
out.topic = "energysaver/downlink/24e124148c400670";
out.payload = {
    "confirmed" : false,
    "fPort"     : 85,
    "data"      : Buffer.from("080000ff", "hex").toString("base64")
};
return out;

/*
Angelo De Florio
indoor_motion_parser.js
*/
// Costanti
const timeout = 0.1; // minuti
const motion  = Number(JSON.parse(msg.payload).pir);
const light   = Number(JSON.parse(msg.payload).light_level);
node.warn(motion);

/*
Funzione createDownlink(hex):
Funzionamento:
    Permette di creare un payload Downlink
    in JSON per inviare determinati
    comandi come l'accensione e lo spegnimento

Parametri:
    - hex: valore esadecimale del payload
*/
function createDownlink(hex) {
    let out = {};
    out.topic = "energysaver/downlink/24e124148c400670";
    out.payload = {
        "confirmed": false,
        "fPort": 85,
        "data": Buffer.from(hex, "hex").toString("base64")
    };
    return out;
}

// Variabile globale Node-RED per memorizzare l'ultimo movimento
let lastMotion = global.get("lastMotion") || Date.now();
// Variabile che contiene il valore esadecimale del payload
let downlinkHex;
/*
Se la persona è presente
o la luce è accesa...
*/
if (motion === 1 || light === 1) {
    // ...allora procedo a verificare lo stato della presa
    // Valore esadecimale di accensione
    downlinkHex = "080100ff"; 
    // Movimento attuale
    global.set("lastMotion", Date.now());

    // Invio lo stato del nodo a Node-RED
    node.status({
        fill: "green",
        shape: "ring",
        text: "Rilevato movimeto! Presa: " + (global.get("socketState") === 1 ? "ON" : "OFF")
    });

    // Se la presa è spenta...
    if (global.get("socketState") !== 1) {
        // ...effettuo l'accensione
        node.warn("Accensione...");
        // aggiorno lo stato globale della presa
        global.set("socketState", 1);
        // chiamo la funzione per creare il payload JSON
        return createDownlink(downlinkHex);
    }

    // Esco dalla funzione
    return null;
}
// ...altrimenti
// calcolo il tempo trascorso in minuti
let elapsed = (Date.now() - lastMotion) / 60000;
// Aggiorno lo stato del nodo in Node-RED segnalando l'assenza
node.status({
    fill: "yellow",
    shape: "ring",
    text: "Assente da " + elapsed.toFixed(3) + " minuti. Presa: " + (global.get("socketState") === 1 ? "ON" : "OFF")
});

// Se il tempo è scaduto e la presa è accesa...
if (elapsed >= timeout && global.get("socketState") !== 0) {
    // ...allora effettuo lo spegnimento
    node.warn("Tempo scaduto! Spegnimento presa in corso...");

    // valore esadecimale di accensione
    downlinkHex = "080000ff";
    // aggiorno lo stato globale della presa
    global.set("socketState", 0);
    // chiamo la funzione per creare il payload JSON
    return createDownlink(downlinkHex);
}

// Esco dalla funzione
return null;

/*
Angelo De Florio
status_parser.js

Interpreta lo stato della presa ricevendo
un payload periodico dal Network Server
tramite broker MQTT
*/
let payload;

// Provo ad effettuare il parsing del payload
try {
    payload = JSON.parse(msg.payload);
} catch (err) {
    node.error("Payload JSON non valido", msg);
return null;

}

/*
Aggiorno lo stato della presa con
una variabile globale del flusso
Node-RED
*/
let state = Number(payload.socket_status);
node.warn("Stato presa: " + state);
if (state === 1 || state === 0) {
    global.set("socketState", state);
}
return null;
